//!441940/441d80 UI attack classification. Query callbacks preserve source
//!ordering and coordinate mutation; they are not inferred from browser orders.
use super::original_selection::Command;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct UnitHit{pub slot:u8,pub group:u8,pub role:i8,pub flags31:u8}
#[derive(Clone,Copy,Debug)]pub struct Input{pub class:u8,pub family:u8,pub actor_slot:u8,pub actor_flags31:u8,pub player:i8,pub grenade_total:u8,pub click:[i16;2],pub fallback_click:[i16;2],pub previous:[i16;3],pub cursor_icon:u16,pub override_ground:Option<[i16;2]>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Query{Repair,Terrain,Building,Destructible,OutOfRange}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Decision{pub event:Option<Command>,pub return_code:u8,pub clear_selection:bool,pub reset_selected_actor:bool,pub icon:Option<u16>,pub target:Option<u8>,pub feedback:bool}
impl Decision{fn none(return_code:u8)->Self{Self{event:None,return_code,clear_selection:false,reset_selected_actor:false,icon:None,target:None,feedback:false}}}
///441940. Repair returns its signed owner byte on hit and adjusts the point.
///For other queries Some(_) means hit. A unit query is already44f5d0's first
///raw-slot hit and can therefore be the actor or a friendly unit.
pub fn infantry(input:Input,hit:Option<UnitHit>,mut query:impl FnMut(Query,&mut [i16;2])->Option<i8>)->Decision{
 if let Some(hit)=hit{if hit.slot==input.actor_slot{return Decision::none(1);}if (hit.flags31^input.actor_flags31)&3==0{return Decision::none(0);}return Decision{event:Some(Command{opcode:5,args:[if hit.role==0{i16::from(hit.slot)}else{-1-i16::from(hit.group)},input.previous[1],0]}),return_code:0,clear_selection:true,reset_selected_actor:true,icon:Some(0xadf),target:Some(hit.slot),feedback:false};}
 if input.grenade_total==0&&matches!(input.class,0|16){return Decision::none(1);}let mut p=input.click;let enemy_repair=query(Query::Repair,&mut p).is_some_and(|owner|i16::from(owner)!=i16::from(input.player));if !enemy_repair&&query(Query::Terrain,&mut p).is_none(){p=input.fallback_click;if query(Query::Building,&mut p).is_none()&&query(Query::Destructible,&mut p).is_none(){return Decision::none(1);}}
 if let Some(override_point)=input.override_ground{p=override_point;}Decision{event:Some(Command{opcode:5,args:[3456,p[0],p[1]]}),return_code:0,clear_selection:true,reset_selected_actor:true,icon:Some(0xadf),target:None,feedback:false}
}
///441d80 plus441bf0's typed target constructor. Ground opcode2 deliberately
///retains62dc48. Fixed guns can send STOP4 with all previous scratcharguments.
pub fn hardware(input:Input,hit:Option<UnitHit>,mut query:impl FnMut(Query,&mut [i16;2])->Option<i8>)->Decision{
 if let Some(hit)=hit{return Decision{event:Some(Command{opcode:2,args:if hit.role==0{[-4321,i16::from(hit.slot),0]}else{[-1234,i16::from(hit.group),0]}}),return_code:0,clear_selection:false,reset_selected_actor:true,icon:Some(0xadf),target:Some(hit.slot),feedback:false};}
 let mut p=input.click;if input.class==2{let stop=if input.cursor_icon!=0xaec&&input.family!=22{if query(Query::OutOfRange,&mut p).is_some(){return Decision::none(0);}query(Query::Terrain,&mut p).is_none()&&query(Query::Destructible,&mut p).is_none()}else{true};if stop{return Decision{event:Some(Command{opcode:4,args:input.previous}),return_code:0,clear_selection:false,reset_selected_actor:false,icon:None,target:None,feedback:false};}}
 let valid=query(Query::Terrain,&mut p).is_some()||query(Query::Destructible,&mut p).is_some();if !valid&&input.class!=2{return Decision::none(0);}Decision{event:Some(Command{opcode:2,args:[p[0],p[1],input.previous[2]]}),return_code:0,clear_selection:valid,reset_selected_actor:valid,icon:Some(0xadf),target:None,feedback:valid}
}
///45afb0. Hardware range is W+5, with its native class/family adjustments.
pub fn out_of_range(actor:[i16;2],point:[i16;2],class:u8,family:u8,range:u8)->bool{let dx=i32::from(actor[0])-i32::from(point[0])+12;let dy=i32::from(actor[1])-i32::from(point[1])+8;let distance=dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy));let radius=if matches!(class,1|2){if family==32{u32::from(range.max(1))}else{u32::from(range)+1}}else{u32::from(range)};distance>(radius.wrapping_mul(8).wrapping_pow(2)as i32)}
#[derive(Clone,Copy,Debug)]pub struct Destructible{pub position:[i16;2],pub template_flags18:u8}
///43ea80 uses metadata18 and half-open bounds, ignoring runtimeflags13.
pub fn destructible_at(objects:&[Destructible],point:[i16;2])->Option<usize>{objects.iter().take(200).position(|o|{let extent=((i16::from(o.template_flags18 as i8)+1)*8)&24;o.position[0]>=0&&o.template_flags18&16!=0&&(0..2).all(|a|o.position[a]<=point[a]&&i32::from(point[a])<i32::from(o.position[a])+i32::from(extent))})}
#[derive(Clone,Copy,Debug)]pub struct RepairBuilding{pub position:[i16;2],pub kind:i8,pub hp:i16,pub remaining:i32,pub offset3a:i8,pub owner:u8}
///41c3f0's repair door band, before the ordinary BUILD hit test.
pub fn repair_at(buildings:&[RepairBuilding],point:[i16;2])->Option<(usize,[i16;2],i8)>{buildings.iter().take(35).enumerate().find_map(|(i,b)|{let y=i32::from(b.position[1])+i32::from(b.offset3a);(b.kind==0&&b.hp!=0&&b.remaining==0&&b.position[0]<=point[0]&&point[0]<=b.position[0].wrapping_add(80)&&y<=i32::from(point[1])&&point[1]<=(y+32)as i16).then_some((i,[b.position[0].wrapping_add(32),b.position[1].wrapping_add(24)],(b.owner&7)as i8))})}
