///44a660's raw admission value, including values2/3 that callers testnonzero.
pub fn terrain_admission(code:u8,class:u8,family:u8,saved_class:u8,grenades:u8)->u8{let table=if class==15{if grenades!=0{0}else{1}}else if family==38{3}else if family==32&&saved_class==15{1}else{2};TERRAIN[table][usize::from(code&127)]}
#[derive(Clone,Copy,Debug)]pub struct Selectable{pub position:[i16;2],pub family:i8,pub flags31:u8,pub flags8a:u8,pub phase35:u8}
///44f5d0, first UNITslot within the source family-adjusted click rectangle.
pub fn unit_at(units:&[Selectable],point:[i16;2],inside_view:bool)->Option<usize>{if !inside_view{return None;}units.iter().take(240).position(|u|{if u.flags31&4==0||u.flags8a&16!=0||u.phase35==18{return false;}let adjustment=if u.family== -1{[0;4]}else{let Some(&kind)=FAMILY_RECT.get(u.family as usize)else{return false;};let Some(&r)=RECTS.get(kind as usize)else{return false;};r};let rect=[point[0].wrapping_sub(14).wrapping_add(adjustment[0]),point[1].wrapping_sub(14).wrapping_add(adjustment[1]),point[0].wrapping_sub(2).wrapping_add(adjustment[2]),point[1].wrapping_sub(2).wrapping_add(adjustment[3])];rect[0]<=u.position[0]&&u.position[0]<=rect[2]&&rect[1]<=u.position[1]&&u.position[1]<=rect[3]})}
