 #[test]fn classifiers_match_1024_real_native_dispatch_sequences(){for branch in 0..2{let mut hash=2166136261;for s in 0..512usize{let input=Input{class:if branch==0{[0,15,16,17,18][s%5]}else if s%3==0{2}else{1},family:if branch==1&&s%5==0{22}else{4},actor_slot:0,actor_flags31:4,player:0,grenade_total:u8::from(s%3!=0),click:[200+(s%80)as i16,300+(s%70)as i16],fallback_click:[400+(s%30)as i16,500+(s%20)as i16],previous:[111,222,333],cursor_icon:if s&64!=0{0xaec}else{0xadf},override_ground:(s&128!=0).then_some([600,700])};let mode=s%8;let hit=(1..=5).contains(&mode).then_some(if mode==1{UnitHit{slot:0,group:0,role:0,flags31:4}}else{UnitHit{slot:1,group:17,role:if s%3==0{0}else{-1},flags31:4+(s%2)as u8}});let mut queries=if branch==0{1}else{21};if branch==0&&hit.is_none(){queries=queries*10+3;if !(input.grenade_total==0&&matches!(input.class,0|16)){queries=queries*10+2;}}let mut query=|q:Query,p:&mut [i16;2]|{let(tag,hit)=match q{Query::Repair=>{p[0]+=3;p[1]-=5;(4,s&1!=0)},Query::Terrain=>(5,s&4!=0),Query::Building=>{p[0]+=7;p[1]-=11;(6,s&16!=0)},Query::Destructible=>(7,s&8!=0),Query::OutOfRange=>(8,s&32!=0)};queries=queries*10+tag;hit.then_some(if q==Query::Repair&&s&2!=0{1}else{0})};let r=if branch==0{infantry(input,hit,&mut query)}else{hardware(input,hit,&mut query)};let c=r.event.unwrap_or(Command{opcode:0,args:[0;3]});let values=[branch,s as i64,r.event.is_some()as i64,i64::from(c.opcode),i64::from(c.args[0]),i64::from(c.args[1]),i64::from(c.args[2]),r.icon.map_or(-1,i64::from),r.clear_selection as i64,r.feedback as i64,i64::from(r.return_code),queries];if std::env::var_os("Z_NATIVE_ATTACK_DUMP").is_some(){println!("{values:?}");}for n in values{mix(&mut hash,n);}}assert_eq!(hash,if branch==0{2707736327}else{1251106293},"real441940/441d80, unit/spatial queries and recursive45ef00 are explicit recorded boundaries");}}
 #[test]fn geometry_matches_1280_actual_native_calls_without_stubs(){let mut hash=2166136261;for s in 0..256usize{let p=[400+(s%50)as i16,500+(s%40)as i16];let units=(0..8).map(|i|Selectable{position:[p[0]-30+((s+i*7)%40)as i16,p[1]-30+((s*3+i*11)%40)as i16],family:[4,6,24,25,30,32,34,36,38,-1][(s+i)%10],flags31:if(s+i)%4==0{0}else{4},flags8a:if(s+i)%7==0{16}else{0},phase35:if(s+i)%5==0{18}else{0}}).collect::<Vec<_>>();let unit=unit_at(&units,p,s%13!=0).map_or(-1,|i|i as i64);let terrain=terrain_admission(s as u8,[0,15,16,17,18,1][s%6],[4,38,32,22][s%4],[0,15,16,17,18][s%5],(s*17)as u8);let objects=(0..16).map(|i|Destructible{position:[if s%17==0{-1}else{p[0]-24+((s+i*3)%32)as i16},p[1]-24+((s*5+i*7)%32)as i16],template_flags18:(s+i*13)as u8}).collect::<Vec<_>>();let object=destructible_at(&objects,p).map_or(-1,|i|i as i64);let buildings=(0..4).map(|i|RepairBuilding{position:[p[0]-40+((s+i*9)%48)as i16,p[1]-40+((s*3+i*13)%48)as i16],kind:0,hp:if(s+i)%7==0{0}else{100},remaining:if(s+i)%5==0{1}else{0},offset3a:-20+((s+i*17)%71)as i8,owner:((s+i)%8)as u8}).collect::<Vec<_>>();let repair=repair_at(&buildings,p);let point=repair.map_or(p,|r|r.1);let range=out_of_range([p[0]-50+(s%100)as i16,p[1]-40+(s%80)as i16],p,[0,1,2,15][s%4],if s%3==0{32}else{6},(s%128)as u8);for n in[s as i64,unit,i64::from(terrain),object,repair.map_or(-1,|r|r.0 as i64),i64::from(point[0]),i64::from(point[1]),repair.map_or(-1,|r|i64::from(r.2)),range as i64]{mix(&mut hash,n);}}assert_eq!(hash,851950173,"actual44f5d0/44a660/43ea80/41c3f0/45afb0, no stubs");}
